def solve(n, probabilities):
    if n == 1:
        return probabilities[0]

    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        for j in range(i, 0, -1):
            dp[j] = max(dp[j] * (1 - probabilities[i-1]), dp[j-1] * probabilities[i-1])

    return max(dp[1:])

n = int(input())
probabilities = list(map(float, input().split()))

result = solve(n, probabilities)
print(f"{result:.12f}")

def calculate_probability(n, probabilities):
    total_probability = 0
    for i in range(n):
        friend_probability = probabilities[i]
        others_probability = 1 - friend_probability
        for j in range(n):
            if j != i:
                others_probability *= (1 - probabilities[j])
        total_probability += friend_probability * others_probability

    return total_probability

