def max_probability_no_upset(n, probabilities):
    def calculate_probability(ask_all):
        prob = 1.0
        for p in probabilities:
            if ask_all:
                prob *= p
            else:
                prob *= p
        return prob

    # Check all combinations to find the one that maximizes the probability of not getting upset
    max_prob = 0.0
    for i in range(1, 1 << n):
        ask_all = (i == (1 << n) - 1)
        prob = calculate_probability(ask_all)
        if ask_all:
            max_prob = max(max_prob, prob)
        else:
            max_prob = max(max_prob, 1 - prob)

    return max_prob

