    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    probabilities = list(map(float, data[1:]))

    def max_probability_not_upset(n, probabilities):
        max_prob = 0.0
        for i in range(n + 1):
            current_prob = 0.0
            for j in range(n):
                if i > 0:
                    # Calculate probability for at least one friend giving a problem
                    current_prob += (probabilities[j] if j < i else 1.0 - probabilities[j])
                # Calculate probability for exactly i friends giving a problem
                if i == 0:
                    current_prob *= (1.0 - probabilities[j])
                else:
                    current_prob *= probabilities[j]
            if i > 0:
                current_prob = 1.0 - (1.0 - current_prob) ** i
            max_prob = max(max_prob, current_prob)
        return max_prob

    result = max_probability_not_upset(n, probabilities)
    print(f"{result:.12f}")

